{"command":"set -e
for seq in 'd-wait' 'd-enter' 'd-d' 'd-Cm' 'd-space' 'd-q'; do
  rm -rf /tmp/walkdel && mkdir /tmp/walkdel && touch /tmp/walkdel/a /tmp/walkdel/b /tmp/walkdel/c
  echo "### $seq"
  tmux kill-session -t walkobs 2>/dev/null || true
  tmux new-session -d -s walkobs -x 80 -y 14 "cd /workspace && TERM=xterm-256color bash -lc './executable /tmp/walkdel; echo RC:\$?; sleep 2'"
  sleep .3
  case $seq in
    d-wait) tmux send-keys -t walkobs d; sleep 1;;
    d-enter) tmux send-keys -t walkobs d; sleep .1; tmux send-keys -t walkobs Enter;;
    d-d) tmux send-keys -t walkobs d; sleep .1; tmux send-keys -t walkobs d;;
    d-Cm) tmux send-keys -t walkobs d; sleep .1; tmux send-keys -t walkobs C-m;;
    d-space) tmux send-keys -t walkobs d; sleep .1; tmux send-keys -t walkobs Space;;
    d-q) tmux send-keys -t walkobs d; sleep .1; tmux send-keys -t walkobs q;;
  esac
  sleep .3
  echo '--pane--'; tmux capture-pane -t walkobs -p -e | sed -n '1,16p' | cat -v
  echo '--files--'; find /tmp/walkdel -maxdepth 1 -type f -printf '%f\n' | sort
  tmux send-keys -t walkobs C-c 2>/dev/null || true
  echo
 done"}

{"command":"cat > main.go <<'EOF'
package main

import (
    "bufio"
    "bytes"
    "errors"
    "fmt"
    "io"
    "os"
    "os/exec"
    "os/signal"
    "os/user"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
    "syscall"
    "time"
    "unicode/utf8"
    "unsafe"
)

const version = "v1.13.0"

const helpText = `
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode

`

const tuiHelp = `    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help`

type termios syscall.Termios

type winsize struct{ Row, Col, Xpixel, Ypixel uint16 }

func ioctl(fd uintptr, req uintptr, arg uintptr) error {
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, req, arg)
    if errno != 0 { return errno }
    return nil
}

func getTermios(fd int) (*syscall.Termios, error) {
    var t syscall.Termios
    err := ioctl(uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&t)))
    return &t, err
}

func setTermios(fd int, t *syscall.Termios) error {
    return ioctl(uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(t)))
}

func makeRaw(fd int) (*syscall.Termios, error) {
    old, err := getTermios(fd)
    if err != nil { return nil, err }
    raw := *old
    raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
    raw.Oflag &^= syscall.OPOST
    raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
    raw.Cflag &^= syscall.CSIZE | syscall.PARENB
    raw.Cflag |= syscall.CS8
    raw.Cc[syscall.VMIN] = 1
    raw.Cc[syscall.VTIME] = 0
    if err := setTermios(fd, &raw); err != nil { return nil, err }
    return old, nil
}

func termSize(fd int) (int,int) {
    ws := winsize{Row:24, Col:80}
    _ = ioctl(uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
    if ws.Col == 0 { ws.Col = 80 }
    if ws.Row == 0 { ws.Row = 24 }
    return int(ws.Col), int(ws.Row)
}

type Config struct {
    icons, dirOnly, hideHidden, preview, border, fuzzy bool
    path string
}

type Entry struct {
    Name string
    Path string
    IsDir bool
    Mode os.FileMode
    Size int64
    Mod time.Time
    Info os.FileInfo
}

type App struct {
    cfg Config
    cwd string
    entries []Entry
    filtered []int
    selected int
    top int
    lastErr error
    query string
    showHelp bool
    msg string
    msgColor int
    deleting bool
    pendingDelete *Entry
    deleteDeadline time.Time
    deleteDone bool
    width, height int
    fd int
    in *os.File
    out *os.File
    mainColor string
    statusExpr string
    selectBg string
}

func main() {
    cfg := parseArgs(os.Args[1:])
    if cfg.path == "__HELP__" { fmt.Fprint(os.Stderr, helpText); os.Exit(1) }
    if cfg.path == "__VERSION__" { fmt.Println(version); return }

    // The original tries to open /dev/tty and panics when there is no controlling tty.
    tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
    if err != nil {
        fmt.Fprintf(os.Stderr, "panic: could not open a new TTY: %v\n\n", err)
        fmt.Fprintln(os.Stderr, "goroutine 1 [running]:")
        fmt.Fprintln(os.Stderr, "main.main()")
        fmt.Fprintln(os.Stderr, "\t/workspace/main.go:135 +0x87d")
        os.Exit(2)
    }
    defer tty.Close()

    app := &App{cfg: cfg, cwd: absPath(cfg.path), fd: int(tty.Fd()), in: tty, out: tty, msgColor:59}
    app.mainColor = os.Getenv("WALK_MAIN_COLOR")
    app.selectBg = colorSeq(app.mainColor, 99)
    app.statusExpr = os.Getenv("WALK_STATUS_BAR")
    if app.statusExpr != "" && !validStatusExpr(app.statusExpr) {
        // Match the visible shape of the expr compiler panic.
        fmt.Fprintf(os.Stderr, "panic: unknown name %s (1:1)\n | %s\n | ^\n\n", strings.TrimSuffix(app.statusExpr, "()"), app.statusExpr)
        fmt.Fprintln(os.Stderr, "goroutine 1 [running]:")
        fmt.Fprintln(os.Stderr, "main.compile({0xc00001e088, 0x"+strconv.FormatInt(int64(len(app.statusExpr)),16)+"})")
        fmt.Fprintln(os.Stderr, "\t/workspace/status_bar.go:16 +0xc5")
        fmt.Fprintln(os.Stderr, "main.main()")
        fmt.Fprintln(os.Stderr, "\t/workspace/main.go:71 +0x127")
        os.Exit(2)
    }

    old, err := makeRaw(app.fd)
    if err != nil {
        fmt.Fprintf(os.Stderr, "panic: %v\n", err)
        os.Exit(2)
    }
    defer setTermios(app.fd, old)
    signal.Ignore(syscall.SIGINT)

    code := app.run()
    setTermios(app.fd, old)
    if code == 0 {
        fmt.Fprintln(os.Stdout, app.cwd)
    }
    os.Exit(code)
}

func parseArgs(args []string) Config {
    cfg := Config{path:"."}
    for _, a := range args {
        switch a {
        case "--help", "-h": cfg.path="__HELP__"; return cfg
        case "--version", "-v": cfg.path="__VERSION__"; return cfg
        case "--icons": cfg.icons=true
        case "--dir-only": cfg.dirOnly=true
        case "--hide-hidden": cfg.hideHidden=true
        case "--preview": cfg.preview=true
        case "--with-border": cfg.border=true
        case "--fuzzy": cfg.fuzzy=true
        default:
            if cfg.path == "." { cfg.path = a }
        }
    }
    return cfg
}

func absPath(p string) string {
    if p == "" { p = "." }
    if !filepath.IsAbs(p) {
        wd, _ := os.Getwd()
        p = filepath.Join(wd, p)
    }
    p = filepath.Clean(p)
    if p == "." { wd,_:=os.Getwd(); p=wd }
    return p
}

func colorSeq(val string, def int) string {
    if val == "" { return fmt.Sprintf("\x1b[48;5;%dm", def) }
    if n, err := strconv.Atoi(val); err == nil {
        if n >= 0 && n <= 7 { return fmt.Sprintf("\x1b[4%dm", n) }
        if n >= 0 && n <= 255 { return fmt.Sprintf("\x1b[48;5;%dm", n) }
    }
    if strings.HasPrefix(val, "#") && len(val) == 7 {
        r, _ := strconv.ParseInt(val[1:3], 16, 0)
        g, _ := strconv.ParseInt(val[3:5], 16, 0)
        b, _ := strconv.ParseInt(val[5:7], 16, 0)
        idx := rgbTo256(int(r), int(g), int(b))
        return fmt.Sprintf("\x1b[48;5;%dm", idx)
    }
    return ""
}
func rgbTo256(r,g,b int) int {
    if r > 200 && g < 80 && b < 80 { return 196 }
    rr := int(float64(r)/256*6); if rr>5 {rr=5}
    gg := int(float64(g)/256*6); if gg>5 {gg=5}
    bb := int(float64(b)/256*6); if bb>5 {bb=5}
    return 16 + 36*rr + 6*gg + bb
}

func (a *App) run() int {
    a.reload("")
    a.draw()
    reader := bufio.NewReader(a.in)
    ticker := time.NewTicker(200 * time.Millisecond)
    defer ticker.Stop()
    keyCh := make(chan string, 1)
    go func(){ for { k,err:=readKey(reader); if err!=nil { close(keyCh); return }; keyCh<-k } }()
    for {
        select {
        case <-ticker.C:
            if a.pendingDelete != nil && !a.deleteDone {
                left := int(time.Until(a.deleteDeadline).Seconds()+0.999)
                if left < 0 { left = 0 }
                a.msg = fmt.Sprintf("%s deleted. (u)ndo %d", a.pendingDelete.Name, left)
                a.msgColor = 196
                if time.Now().After(a.deleteDeadline) {
                    _ = removePath(a.pendingDelete.Path)
                    a.deleteDone = true
                    a.reload("")
                }
                a.draw()
            }
        case k, ok := <-keyCh:
            if !ok { return 2 }
            switch a.handle(k) {
            case 0: a.draw()
            case 1: return 0
            case 2: return 2
            }
        }
    }
}

func readKey(r *bufio.Reader) (string,error) {
    b, err := r.ReadByte(); if err != nil { return "", err }
    switch b {
    case 3: return "ctrl-c", nil
    case 13,10: return "enter", nil
    case 127,8: return "backspace", nil
    case 27:
        // Escape sequence if available shortly, otherwise ESC.
        time.Sleep(10*time.Millisecond)
        if r.Buffered() == 0 { return "esc", nil }
        b2,_ := r.ReadByte()
        if b2 != '[' && b2 != 'O' { return "esc", nil }
        seq := []byte{b2}
        for r.Buffered() > 0 {
            c,_ := r.ReadByte(); seq = append(seq,c)
            if (c >= 'A' && c <= 'Z') || c == '~' { break }
        }
        s := string(seq)
        switch {
        case strings.HasSuffix(s,"A"): return "up", nil
        case strings.HasSuffix(s,"B"): return "down", nil
        case strings.HasSuffix(s,"C"): return "right", nil
        case strings.HasSuffix(s,"D"): return "left", nil
        case s == "[H" || s == "[1~" || s == "[7~": return "home", nil
        case s == "[F" || s == "[4~" || s == "[8~": return "end", nil
        case strings.HasSuffix(s,"3~"): return "delete", nil
        }
        return "esc", nil
    default:
        return string([]byte{b}), nil
    }
}

func (a *App) handle(k string) int {
    if a.showHelp {
        if k == "ctrl-c" { return 2 }
        if k == "q" || k == "esc" || k == "?" || k == "enter" || k == "backspace" { a.showHelp=false; return 0 }
        return 0
    }
    if a.deleting {
        if k == "d" || k == "delete" { a.confirmDelete(); a.deleting=false; return 0 }
        if k == "ctrl-c" { return 2 }
        a.deleting=false
        // continue handling normal key except for plain cancel-ish keys
        if k == "n" || k == "esc" { return 0 }
    }
    if a.cfg.fuzzy && len(k)==1 && k >= " " && k != "\x7f" && k != "/" && k != "q" {
        // In fuzzy mode printable characters build the query, except command letters below when no query.
        if !(a.query=="" && strings.Contains("hjkl.dyu?", k)) {
            a.query += k; a.applyFuzzy(); return 0
        }
    }
    switch k {
    case "ctrl-c": return 2
    case "q", "esc": return 1
    case "up", "k": a.move(-1)
    case "down", "j": a.move(1)
    case "home": a.selected=0
    case "end": if len(a.filtered)>0 { a.selected=len(a.filtered)-1 }
    case "left", "h", "backspace": a.goParent()
    case "right", "l", "enter": a.enter()
    case " ": a.cfg.preview = !a.cfg.preview
    case "/": a.cfg.fuzzy=true; a.query=""; a.applyFuzzy()
    case ".": a.cfg.hideHidden = !a.cfg.hideHidden; a.reload("")
    case "?": a.showHelp=true
    case "y": a.yank()
    case "d", "delete": if len(a.filtered)>0 { a.deleting=true; a.msg="" }
    case "u": a.undoDelete()
    case "backspace-query":
    default:
        if a.cfg.fuzzy {
            if k == "backspace" && a.query != "" { a.query = trimLastRune(a.query); a.applyFuzzy() }
        }
    }
    return 0
}

func trimLastRune(s string) string { if s=="" {return s}; _,sz:=utf8.DecodeLastRuneInString(s); return s[:len(s)-sz] }

func (a *App) move(d int) {
    n := len(a.filtered); if n==0 { return }
    a.selected = (a.selected + d) % n
    if a.selected < 0 { a.selected += n }
    a.ensureVisible()
}

func (a *App) ensureVisible() {
    maxRows := a.listRows()
    if a.selected < a.top { a.top = a.selected }
    if a.selected >= a.top + maxRows { a.top = a.selected - maxRows + 1 }
    if a.top < 0 { a.top = 0 }
}

func (a *App) current() *Entry {
    if len(a.filtered)==0 || a.selected<0 || a.selected>=len(a.filtered) { return nil }
    return &a.entries[a.filtered[a.selected]]
}

func (a *App) enter() {
    e := a.current(); if e == nil { return }
    if e.IsDir { a.cwd=e.Path; a.cfg.fuzzy=false; a.query=""; a.reload(""); return }
    a.openFile(e.Path)
    a.reload(e.Name)
}

func (a *App) goParent() {
    parent := filepath.Dir(a.cwd)
    if parent == a.cwd { return }
    old := filepath.Base(a.cwd)
    a.cwd = parent; a.cfg.fuzzy=false; a.query=""; a.reload(old)
}

func (a *App) yank() {
    e := a.current(); if e == nil { return }
    a.msg = "copied: " + e.Path
    a.msgColor = 59
}

func (a *App) confirmDelete() {
    e := a.current(); if e == nil { return }
    cp := *e
    a.pendingDelete = &cp
    a.deleteDone = false
    a.deleteDeadline = time.Now().Add(5*time.Second)
    a.msg = fmt.Sprintf("%s deleted. (u)ndo 5", e.Name)
    a.msgColor = 196
    // Hide immediately from the list, remove later.
    name := e.Name
    out := a.entries[:0]
    for _, x := range a.entries { if x.Name != name { out = append(out, x) } }
    a.entries = out; a.rebuildFiltered()
    if a.selected >= len(a.filtered) && a.selected>0 { a.selected-- }
}

func (a *App) undoDelete() {
    if a.pendingDelete != nil && !a.deleteDone { a.pendingDelete=nil; a.msg=""; a.reload("") }
}

func removePath(p string) error {
    if cmd := os.Getenv("WALK_REMOVE_CMD"); cmd != "" {
        c := exec.Command("sh", "-c", cmd+" "+shellQuote(p))
        return c.Run()
    }
    return os.RemoveAll(p)
}
func shellQuote(s string) string { return "'"+strings.ReplaceAll(s,"'","'\\''")+"'" }

func (a *App) openFile(p string) {
    editor := os.Getenv("WALK_EDITOR")
    if editor == "" { editor = os.Getenv("EDITOR") }
    if editor == "" {
        // The original commonly falls back to a pager. If it is absent, silently ignore.
        if _, err := exec.LookPath("less"); err == nil { editor = "less" } else { return }
    }
    setTermios(a.fd, mustGetTerm(a.fd)) // restore-ish below uses raw after command; best effort
    fmt.Fprint(a.out, "\x1b[?25h")
    parts := strings.Fields(editor)
    if len(parts)==0 { return }
    cmd := exec.Command(parts[0], append(parts[1:], p)...)
    cmd.Stdin, cmd.Stdout, cmd.Stderr = a.in, a.out, a.out
    _ = cmd.Run()
    _, _ = makeRaw(a.fd)
}
func mustGetTerm(fd int) *syscall.Termios { t,_ := getTermios(fd); return t }

func (a *App) reload(selectName string) {
    a.lastErr = nil
    infos, err := os.ReadDir(a.cwd)
    if err != nil { a.entries=nil; a.filtered=nil; a.lastErr=err; return }
    a.entries = make([]Entry,0,len(infos))
    for _, de := range infos {
        name := de.Name()
        info, err := de.Info(); if err != nil { continue }
        ent := Entry{Name:name, Path:filepath.Join(a.cwd,name), IsDir:de.IsDir(), Mode:info.Mode(), Size:info.Size(), Mod:info.ModTime(), Info:info}
        a.entries = append(a.entries, ent)
    }
    sort.SliceStable(a.entries, func(i,j int) bool { return strings.ToLower(a.entries[i].Name) < strings.ToLower(a.entries[j].Name) })
    a.rebuildFiltered()
    a.selected = 0
    if selectName != "" {
        for i, idx := range a.filtered { if a.entries[idx].Name == selectName { a.selected = i; break } }
    }
    a.ensureVisible()
}

func (a *App) rebuildFiltered() {
    a.filtered = a.filtered[:0]
    for i,e := range a.entries {
        if a.cfg.hideHidden && strings.HasPrefix(e.Name, ".") { continue }
        if a.cfg.dirOnly && !e.IsDir { continue }
        a.filtered = append(a.filtered, i)
    }
    a.applyFuzzy()
}

func (a *App) applyFuzzy() {
    if !a.cfg.fuzzy || a.query=="" { if a.selected>=len(a.filtered) { a.selected=0 }; return }
    q := strings.ToLower(a.query)
    best := -1
    for i, idx := range a.filtered {
        if fuzzyMatch(strings.ToLower(a.entries[idx].Name), q) { best=i; break }
    }
    if best >= 0 { a.selected=best; a.ensureVisible() }
}
func fuzzyMatch(name,q string) bool {
    pos := 0
    for _, c := range q {
        found := false
        for pos < len(name) {
            r,sz := utf8.DecodeRuneInString(name[pos:]); pos += sz
            if r == c { found=true; break }
        }
        if !found { return false }
    }
    return true
}

func (a *App) draw() {
    a.width, a.height = termSize(a.fd)
    if a.width <= 0 { a.width=80 }; if a.height<=0 { a.height=24 }
    var b strings.Builder
    b.WriteString("\x1b[H\x1b[J")
    b.WriteString("\x1b[?25l")
    if a.showHelp {
        b.WriteString(style("help", 59))
        b.WriteString("\n\n")
        b.WriteString(tuiHelp)
        fmt.Fprint(a.out, b.String())
        return
    }
    if a.cfg.preview { a.drawPreview(&b) } else { a.drawPlain(&b) }
    fmt.Fprint(a.out, b.String())
}

func (a *App) listRows() int {
    rows := a.height - 1
    if a.statusExpr != "" || a.msg != "" { rows-- }
    if rows < 1 { rows=1 }
    return rows
}

func (a *App) drawPlain(b *strings.Builder) {
    header := a.cwd
    b.WriteString(style(header, 59))
    if a.cfg.fuzzy { b.WriteString(styleBg(a.query,70)) }
    b.WriteString("\n")
    if a.lastErr != nil { drawBox(b, a.lastErr.Error()); a.drawBottom(b); return }
    if len(a.filtered)==0 { drawBox(b, "No files"); a.drawBottom(b); return }
    maxName := 0
    names := a.displayNames()
    for _, n := range names { if strWidth(n)>maxName { maxName=strWidth(n) } }
    rows := a.listRows()
    end := min(len(a.filtered), a.top+rows)
    for line:=a.top; line<end; line++ {
        s := padRight(names[line], maxName)
        if line == a.selected {
            if a.deleting { b.WriteString(styleBg(s,196)) } else { b.WriteString(styleSelect(s, a.selectBg)) }
        } else { b.WriteString(s) }
        b.WriteString("\n")
    }
    a.drawBottom(b)
}

func (a *App) drawPreview(b *strings.Builder) {
    names := a.displayNames()
    leftW := 0
    for _, n := range names { if strWidth(n)>leftW { leftW=strWidth(n) } }
    baseHeader := "/"+filepath.Base(a.cwd)
    if leftW < strWidth(baseHeader) { leftW = strWidth(baseHeader) }
    if leftW > a.width/2-2 { leftW = max(1,a.width/2-2) }
    sep := "  "
    if a.cfg.border { sep = " " + fg("│",99) + " " }
    rightW := a.width - leftW - strWidth(stripAnsi(sep))
    if rightW < 10 { rightW = 10 }
    e := a.current()
    rightTitle := ""
    if e != nil { rightTitle = e.Name }
    b.WriteString(style(truncateLeft(baseHeader,leftW),59)); b.WriteString(sep); b.WriteString(style(truncate(rightTitle,rightW),59)); b.WriteString("\n")
    previewLines := a.previewLines(rightW, a.height-1)
    rows := a.listRows()
    if rows < len(previewLines) { rows = len(previewLines) }
    if rows > a.height-1 { rows = a.height-1 }
    for i:=0; i<rows; i++ {
        left := ""
        idxLine := a.top+i
        if idxLine < len(names) { left = padRight(truncate(names[idxLine], leftW), leftW) } else { left = strings.Repeat(" ", leftW) }
        if idxLine == a.selected {
            if a.deleting { left = styleBg(left,196) } else { left = styleSelect(left,a.selectBg) }
        }
        right := ""
        if i < len(previewLines) { right = previewLines[i] }
        b.WriteString(left); b.WriteString(sep); b.WriteString(right); b.WriteString("\n")
    }
    a.drawBottom(b)
}

func (a *App) drawBottom(b *strings.Builder) {
    line := ""
    color := 59
    if a.msg != "" { line=a.msg; color=a.msgColor } else if a.statusExpr != "" { line=a.evalStatus(); color=59 }
    if line != "" { b.WriteString(style(line,color)); b.WriteString("\n") }
}

func (a *App) displayNames() []string {
    names := make([]string, len(a.filtered))
    for i, idx := range a.filtered {
        e := a.entries[idx]
        n := e.Name
        if e.IsDir { n += "/" }
        if a.cfg.icons { n = iconFor(e) + " " + n }
        names[i] = n
    }
    return names
}

func (a *App) previewLines(width, maxLines int) []string {
    e := a.current()
    if e == nil { return boxLines("No preview available", width) }
    if e.IsDir {
        ds, err := os.ReadDir(e.Path)
        if err != nil { return boxLines(err.Error(), width) }
        var ents []string
        for _, d := range ds {
            if a.cfg.hideHidden && strings.HasPrefix(d.Name(), ".") { continue }
            name := d.Name(); if d.IsDir() { name += "/" }
            ents = append(ents, truncate(name,width))
        }
        sort.SliceStable(ents, func(i,j int) bool { return strings.ToLower(ents[i]) < strings.ToLower(ents[j]) })
        if len(ents)==0 { return boxLines("No files", width) }
        if len(ents)>maxLines { ents=ents[:maxLines] }
        return ents
    }
    data, err := os.ReadFile(e.Path)
    if err != nil { return boxLines(err.Error(), width) }
    if isBinary(data) { return boxLines("No preview available", width) }
    data = bytes.ReplaceAll(data, []byte("\t"), []byte("    "))
    ss := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
    if len(ss)==1 && ss[0]=="" { return nil }
    if len(ss)>maxLines { ss=ss[:maxLines] }
    for i := range ss { ss[i]=truncate(ss[i], width) }
    return ss
}

func isBinary(data []byte) bool {
    if len(data)==0 { return false }
    sample := data; if len(sample)>8000 { sample=sample[:8000] }
    for _, c := range sample { if c==0 || (c<7 && c!='\n' && c!='\r' && c!='\t') { return true } }
    if !utf8.Valid(sample) { return true }
    return false
}

func boxLines(msg string, width int) []string {
    w := strWidth(msg)+2
    if width>0 && w>width { w=width }
    inner := max(1,w-2)
    m := truncate(msg, inner)
    return []string{"┌"+strings.Repeat("─",inner)+"┐", "│"+padRight(m,inner)+"│", "└"+strings.Repeat("─",inner)+"┘"}
}
func drawBox(b *strings.Builder, msg string) { for _, l := range boxLines(msg, 0) { b.WriteString(l); b.WriteString("\n") } }

func style(s string, bg int) string { return fmt.Sprintf("\x1b[38;5;231m\x1b[48;5;%dm%s\x1b[39m\x1b[49m", bg, s) }
func styleBg(s string, bg int) string { return style(s,bg) }
func styleSelect(s, bgseq string) string { return "\x1b[38;5;231m"+bgseq+s+"\x1b[39m\x1b[49m" }
func fg(s string, c int) string { return fmt.Sprintf("\x1b[38;5;%dm%s\x1b[39m", c, s) }

func iconFor(e Entry) string {
    if e.IsDir { return "" }
    if e.Mode&0111 != 0 { return "" }
    ext := strings.ToLower(filepath.Ext(e.Name))
    switch ext {
    case ".md", ".markdown", ".mdx": return ""
    case ".go": return ""
    case ".py", ".pyc", ".pyo": return ""
    case ".js", ".mjs": return ""
    case ".json": return ""
    case ".html", ".htm": return ""
    case ".css", ".scss", ".sass": return ""
    case ".sh", ".bash", ".zsh", ".fish": return ""
    case ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp": return ""
    case ".rs": return ""
    case ".c": return ""
    case ".cpp", ".cc", ".cxx", ".hpp": return ""
    case ".txt": return ""
    }
    lname := strings.ToLower(e.Name)
    if lname == "license" { return "" }
    if lname == "makefile" { return "" }
    if lname == "dockerfile" { return "" }
    return ""
}

func validStatusExpr(s string) bool {
    s = strings.TrimSpace(s)
    if s == "" { return true }
    if strings.HasPrefix(s,"\"") && strings.HasSuffix(s,"\"") { return true }
    known := []string{"Size()","Mode()","ModTime()","Owner()","Sprintf(","PadLeft(","PadRight(","join(","current_file","files"}
    if s == "Size()" || s == "Mode()" || s == "ModTime()" || s == "Owner()" { return true }
    if strings.Contains(s,"Mode()") || strings.Contains(s,"Size()") || strings.Contains(s,"ModTime()") || strings.Contains(s,"Owner()") {
        _ = known; return true
    }
    return false
}

func (a *App) evalStatus() string {
    e := a.current(); if e==nil { return "" }
    expr := strings.TrimSpace(a.statusExpr)
    if strings.HasPrefix(expr,"\"") && strings.HasSuffix(expr,"\"") { v,_:=strconv.Unquote(expr); return v }
    if expr == "Size()" { return humanSize(e.Size) }
    if expr == "Mode()" { return modeString(e.Mode) }
    if expr == "ModTime()" { return modTime(e.Mod) }
    if expr == "Owner()" { return ownerString(e.Info) }
    // Common documented ls -l expression.
    if strings.Contains(expr,"Mode()") && strings.Contains(expr,"Owner()") && strings.Contains(expr,"Size()") && strings.Contains(expr,"ModTime()") {
        return strings.Join([]string{modeString(e.Mode), ownerString(e.Info), padLeft(humanSize(e.Size),7), padLeft(modTime(e.Mod),12)}, " ")
    }
    if strings.Contains(expr,"Size()") { return humanSize(e.Size) }
    if strings.Contains(expr,"Mode()") { return modeString(e.Mode) }
    return ""
}

func humanSize(n int64) string {
    if n < 1000 { return fmt.Sprintf("%dB", n) }
    units := []string{"KB","MB","GB","TB"}
    f := float64(n)
    for _, u := range units {
        f /= 1000
        if f < 1000 { return fmt.Sprintf("%.1f%s", f, u) }
    }
    return fmt.Sprintf("%.1fPB", f/1000)
}
func modeString(m os.FileMode) string { return m.String() }
func modTime(t time.Time) string { return t.Format("Jan _2 15:04") }
func ownerString(info os.FileInfo) string {
    st, ok := info.Sys().(*syscall.Stat_t); if !ok { return "" }
    uid, gid := strconv.FormatUint(uint64(st.Uid),10), strconv.FormatUint(uint64(st.Gid),10)
    un, gn := uid, gid
    if u, err := user.LookupId(uid); err==nil { un=u.Username }
    if g, err := user.LookupGroupId(gid); err==nil { gn=g.Name }
    return un+" "+gn
}

func padLeft(s string, n int) string { if strWidth(s)>=n { return s }; return strings.Repeat(" ", n-strWidth(s))+s }
func padRight(s string, n int) string { if strWidth(s)>=n { return s }; return s+strings.Repeat(" ", n-strWidth(s)) }
func truncate(s string, n int) string { if n<=0 { return "" }; if strWidth(s)<=n { return s }; var b strings.Builder; w:=0; for _,r:=range s { rw:=runeWidth(r); if w+rw>n {break}; b.WriteRune(r); w+=rw }; return b.String() }
func truncateLeft(s string, n int) string { if strWidth(s)<=n { return s }; rs:=[]rune(s); for len(rs)>0 && strWidth(string(rs))>n { rs=rs[1:] }; return string(rs) }
func strWidth(s string) int { w:=0; esc:=false; for i:=0;i<len(s); { if s[i]==0x1b { esc=true }; if esc { if s[i]=='m' {esc=false}; i++; continue }; r,sz:=utf8.DecodeRuneInString(s[i:]); w += runeWidth(r); i += sz }; return w }
func runeWidth(r rune) int { if r==utf8.RuneError { return 1 }; if r >= 0x1100 { return 1 }; return 1 }
func stripAnsi(s string) string { var b strings.Builder; esc:=false; for i:=0;i<len(s);i++ { if s[i]==0x1b {esc=true; continue}; if esc { if s[i]=='m' {esc=false}; continue}; b.WriteByte(s[i])}; return b.String() }
func min(a,b int) int { if a<b {return a}; return b }
func max(a,b int) int { if a>b {return a}; return b }

